package pe.edu.utp.cafegest;
import javafx.application.Application;
import javafx.geometry.*;
import javafx.scene.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Stage;
import pe.edu.utp.cafegest.config.Database;
import pe.edu.utp.cafegest.dao.ProductoDao;
import pe.edu.utp.cafegest.model.Producto;
import pe.edu.utp.cafegest.service.*;
import java.math.BigDecimal;
import java.sql.*;
import java.util.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.apache.poi.ss.usermodel.*;
import javafx.stage.FileChooser;
import java.io.*;

/** Vista JavaFX; delega persistencia a DAO y reglas de ventas al servicio. */
public class MainApp extends Application {
    private final ProductoDao dao=new ProductoDao();private final VentaService ventas=new VentaService();private final AuthService auth=new AuthService();
    private Stage stage;private String usuario;private String rol;private final String css="-fx-font-family: 'Segoe UI'; -fx-font-size: 13px;";
    @Override public void start(Stage stage){this.stage=stage;try{Database.init();if(auth.sinUsuarios())setup();else login();}catch(Exception e){error(e);}stage.setTitle("CaféGest | Gestión de cafetería");stage.setWidth(1100);stage.setHeight(720);stage.show();}
    private VBox form(String titulo){VBox v=new VBox(12);v.setPadding(new Insets(28));v.setStyle(css);Label h=new Label(titulo);h.setStyle("-fx-font-size:24px;-fx-font-weight:bold;-fx-text-fill:#543928;");v.getChildren().add(h);return v;}
    private void show(Node n){stage.setScene(new Scene(new StackPane(n)));}
    private void setup(){VBox v=form("CaféGest · Configuración inicial");v.getChildren().add(new Label("Crea una contraseña para el administrador (mínimo 10 caracteres)."));PasswordField p=new PasswordField();p.setPromptText("Nueva contraseña");PasswordField confirm=new PasswordField();confirm.setPromptText("Repetir contraseña");Button b=new Button("Crear administrador");b.setOnAction(e->run(()->{if(!p.getText().equals(confirm.getText()))throw new IllegalArgumentException("Las contraseñas no coinciden");auth.crearAdminInicial(p.getText());login();}));v.getChildren().addAll(p,confirm,b);show(v);}
    private void login(){VBox v=form("☕ CaféGest · Iniciar sesión");TextField u=new TextField();u.setPromptText("Usuario");PasswordField p=new PasswordField();p.setPromptText("Contraseña");Button b=new Button("Ingresar");b.setOnAction(e->run(()->{String r=auth.login(u.getText().trim(),p.getText());if(r==null)throw new IllegalArgumentException("Credenciales incorrectas");usuario=u.getText().trim();rol=r;home();}));v.getChildren().addAll(u,p,b);v.setMaxWidth(430);show(v);}
    private void home(){BorderPane root=new BorderPane();root.setStyle(css+"-fx-background-color:#faf7f4;");VBox nav=new VBox(12);nav.setPadding(new Insets(22));nav.setPrefWidth(210);nav.setStyle("-fx-background-color:#493125;");Label logo=new Label("☕ CaféGest");logo.setStyle("-fx-text-fill:white;-fx-font-size:22px;-fx-font-weight:bold;");nav.getChildren().add(logo);StackPane content=new StackPane();content.setPadding(new Insets(15));root.setLeft(nav);root.setCenter(content);
        String[] names={"Dashboard","Productos","Inventario","Nueva venta","Historial y reportes","Cerrar sesión"};for(int i=0;i<names.length;i++){final int index=i;Button b=new Button(names[i]);b.setMaxWidth(Double.MAX_VALUE);b.setStyle("-fx-background-color:#f0e7dc;-fx-text-fill:#493125;-fx-padding:12px;");b.setOnAction(e->{try{if(index==5){login();return;}content.getChildren().setAll(switch(index){case 0->dashboard();case 1->productos();case 2->inventario();case 3->venta();default->reportes();});}catch(Exception ex){error(ex);}});nav.getChildren().add(b);}if(!"ADMIN".equals(rol)){nav.getChildren().get(2).setDisable(true);nav.getChildren().get(3).setDisable(true);}
        try{content.getChildren().setAll(dashboard());}catch(Exception e){error(e);}show(root);
    }
    private Node dashboard() throws Exception {VBox v=form("Resumen de cafetería");List<Producto> ps=dao.listar();long bajos=ps.stream().filter(p->p.stock()<=p.minimo()).count();v.getChildren().addAll(new Label("Usuario: "+usuario+" | Rol: "+rol),new Label("Productos activos: "+ps.size()),new Label("Productos con stock bajo: "+bajos));try(Connection c=Database.open();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*),COALESCE(SUM(total),0) FROM ventas")){r.next();v.getChildren().add(new Label("Ventas registradas: "+r.getInt(1)+" | Ingresos: S/ "+r.getBigDecimal(2)));}return v;}
    private Node productos() throws Exception {VBox v=form("Gestión de productos terminados");TableView<Producto> t=tabla();v.getChildren().add(t);TextField nombre=new TextField(),cat=new TextField(),precio=new TextField(),stock=new TextField(),minimo=new TextField();nombre.setPromptText("Nombre (ej. Café expreso)");cat.setPromptText("Categoría");precio.setPromptText("Precio S/");stock.setPromptText("Stock inicial");minimo.setPromptText("Stock mínimo");HBox inputs=new HBox(8,nombre,cat,precio,stock,minimo);v.getChildren().add(inputs);Button guardar=new Button("Guardar producto"),editar=new Button("Actualizar seleccionado"),baja=new Button("Desactivar seleccionado");guardar.setOnAction(e->run(()->{validarProducto(nombre,cat,precio,stock,minimo);dao.guardar(null,nombre.getText().trim(),cat.getText().trim(),new BigDecimal(precio.getText()),Integer.parseInt(stock.getText()),Integer.parseInt(minimo.getText()));t.getItems().setAll(dao.listar());}));editar.setOnAction(e->run(()->{Producto p=seleccion(t);validarProducto(nombre,cat,precio,stock,minimo);dao.guardar(p.id(),nombre.getText().trim(),cat.getText().trim(),new BigDecimal(precio.getText()),Integer.parseInt(stock.getText()),Integer.parseInt(minimo.getText()));t.getItems().setAll(dao.listar());}));baja.setOnAction(e->run(()->{dao.desactivar(seleccion(t).id());t.getItems().setAll(dao.listar());}));t.getSelectionModel().selectedItemProperty().addListener((o,a,p)->{if(p!=null){nombre.setText(p.nombre());cat.setText(p.categoria());precio.setText(p.precio().toPlainString());stock.setText(""+p.stock());minimo.setText(""+p.minimo());}});if(!"ADMIN".equals(rol)){guardar.setDisable(true);editar.setDisable(true);baja.setDisable(true);}v.getChildren().add(new HBox(10,guardar,editar,baja));return v;}
    private void validarProducto(TextField n,TextField c,TextField p,TextField s,TextField m){if(n.getText().isBlank()||c.getText().isBlank())throw new IllegalArgumentException("Nombre y categoría requeridos");if(new BigDecimal(p.getText()).signum()<0||Integer.parseInt(s.getText())<0||Integer.parseInt(m.getText())<0)throw new IllegalArgumentException("No se permiten valores negativos");}
    private TableView<Producto> tabla() throws Exception {TableView<Producto> t=new TableView<>();String[] cols={"ID","Nombre","Categoría","Precio S/","Stock","Mínimo"};java.util.List<java.util.function.Function<Producto,String>> getters=java.util.List.of(p->""+p.id(),p->p.nombre(),p->p.categoria(),p->p.precio().toPlainString(),p->""+p.stock(),p->""+p.minimo());for(int i=0;i<cols.length;i++){TableColumn<Producto,String> col=new TableColumn<>(cols[i]);var getter=getters.get(i);col.setCellValueFactory(data->new javafx.beans.property.SimpleStringProperty(getter.apply(data.getValue())));col.setPrefWidth(i==1?210:115);t.getColumns().add(col);}t.getItems().setAll(dao.listar());t.setPrefHeight(360);return t;}
    private Producto seleccion(TableView<Producto> t){Producto p=t.getSelectionModel().getSelectedItem();if(p==null)throw new IllegalArgumentException("Selecciona un producto");return p;}
    private Node inventario() throws Exception {VBox v=form("Inventario · Productos terminados");TableView<Producto> t=tabla();v.getChildren().addAll(new Label("Reposiciones y ajustes: cantidades positivas para entradas, negativas para salidas."),t);TextField cantidad=new TextField();cantidad.setPromptText("Cantidad (+ o -)");TextField motivo=new TextField();motivo.setPromptText("Motivo del movimiento");Button b=new Button("Registrar movimiento");b.setOnAction(e->run(()->{if(motivo.getText().isBlank())throw new IllegalArgumentException("Indica el motivo");int delta=Integer.parseInt(cantidad.getText());if(delta==0)throw new IllegalArgumentException("Cantidad no puede ser cero");dao.ajustar(seleccion(t).id(),delta,motivo.getText());t.getItems().setAll(dao.listar());}));if(!"ADMIN".equals(rol))b.setDisable(true);v.getChildren().add(new HBox(10,cantidad,motivo,b));return v;}
    private Node venta() throws Exception {VBox v=form("Registrar nueva venta");ComboBox<Producto> productos=new ComboBox<>();productos.getItems().setAll(dao.listar());productos.setPrefWidth(320);Spinner<Integer> cantidad=new Spinner<>(1,1000,1);ListView<String> detalle=new ListView<>();detalle.setPrefHeight(230);List<VentaService.Linea> carrito=new ArrayList<>();Button agregar=new Button("Agregar al carrito");agregar.setOnAction(e->run(()->{Producto p=productos.getValue();if(p==null)throw new IllegalArgumentException("Selecciona un producto");int q=cantidad.getValue();carrito.add(new VentaService.Linea(p.id(),q));detalle.getItems().add(q+" × "+p.nombre()+" = S/ "+p.precio().multiply(BigDecimal.valueOf(q)));}));Button confirmar=new Button("Confirmar venta");confirmar.setOnAction(e->run(()->{int id=ventas.vender(usuario,carrito);new Alert(Alert.AlertType.INFORMATION,"Venta #"+id+" registrada y stock descontado").showAndWait();carrito.clear();detalle.getItems().clear();productos.getItems().setAll(dao.listar());}));v.getChildren().addAll(new HBox(10,productos,cantidad,agregar),detalle,confirmar);return v;}
    private Node reportes() throws Exception {VBox v=form("Historial de ventas y reportes");TableView<String[]> t=new TableView<>();String[] cols={"ID","Fecha","Usuario","Total S/"};for(int i=0;i<4;i++){final int idx=i;TableColumn<String[],String> c=new TableColumn<>(cols[i]);c.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue()[idx]));c.setPrefWidth(190);t.getColumns().add(c);}try(Connection c=Database.open();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,fecha,usuario,total FROM ventas ORDER BY id DESC")){while(r.next())t.getItems().add(new String[]{r.getString(1),r.getString(2),r.getString(3),r.getString(4)});}Button export=new Button("Exportar ventas a Excel");export.setOnAction(e->run(()->{FileChooser f=new FileChooser();f.setInitialFileName("ventas_cafegest.xlsx");f.getExtensionFilters().add(new FileChooser.ExtensionFilter("Excel","*.xlsx"));File file=f.showSaveDialog(stage);if(file==null)return;try(XSSFWorkbook wb=new XSSFWorkbook();FileOutputStream out=new FileOutputStream(file)){Sheet sh=wb.createSheet("Ventas");Row header=sh.createRow(0);for(int i=0;i<cols.length;i++)header.createCell(i).setCellValue(cols[i]);int row=1;for(String[] values:t.getItems()){Row rr=sh.createRow(row++);for(int i=0;i<values.length;i++)rr.createCell(i).setCellValue(values[i]);}wb.write(out);}new Alert(Alert.AlertType.INFORMATION,"Excel exportado").showAndWait();}));v.getChildren().addAll(t,export);return v;}
    private interface Action{void run() throws Exception;}
    private void run(Action a){try{a.run();}catch(Exception e){error(e);}}
    private void error(Exception e){new Alert(Alert.AlertType.ERROR,e.getMessage()==null?e.toString():e.getMessage()).showAndWait();}
    public static void main(String[] args){launch(args);}
}
